insert into status_steps (position, as_of, name, state, detail) values
  (1, '2026-10-24', 'main requires a pull request', 'Done', 'Admins included. A builder session''s push was blocked. Repository settings are not public, so this line carries a date and no link.'),
  (2, '2026-10-25', 'Ops watch checks the site nightly', 'Done', 'Installed by `setup` in [PR #2](https://github.com/todd450/founding-agents-site/pull/2); first run green. A red run by hand opened [#3](https://github.com/todd450/founding-agents-site/issues/3) and closed it on green.'),
  (3, '2026-10-26', 'build runs to merge on real issues', 'Done · 4 of 3–5', 'Four runs have merged on real issues: [issue #4](https://github.com/todd450/founding-agents-site/issues/4), built in [PR #7](https://github.com/todd450/founding-agents-site/pull/7); [issue #5](https://github.com/todd450/founding-agents-site/issues/5), built in [PR #8](https://github.com/todd450/founding-agents-site/pull/8); [issue #6](https://github.com/todd450/founding-agents-site/issues/6), built in [PR #9](https://github.com/todd450/founding-agents-site/pull/9); and [issue #10](https://github.com/todd450/founding-agents-site/issues/10), built in [PR #11](https://github.com/todd450/founding-agents-site/pull/11) — this merge itself. Four of the three to five build issues this step needed are now in, so the step is done.'),
  (4, '2026-10-26', 'propose reaches the founder as one item', 'Done', 'Its done condition was one real run on this site''s brief, and that run is the queue item on [issue #1](https://github.com/todd450/founding-agents-site/issues/1), which reached the founder on 26 Oct 2026.');
insert into costs (position, as_of, figure, lead, claim, source) values
  (1, '2026-10-26', '5,410', 'Volume nobody can read.', 'Commits in under five months — more change than one person can review, let alone remember.', 'Recorded 26 Oct 2026'),
  (2, '2026-10-26', '61,365 lines, in 8 days', 'Work undone as fast as it was done.', 'Thirty-two removal commits deleting what had just been written.', 'Recorded 26 Oct 2026'),
  (3, '2026-10-26', '731', 'Sweeping up after the fact.', 'Bug-sweep and audit commits: quality bolted on at the end instead of decided at the start.', 'Recorded 26 Oct 2026'),
  (4, '2026-10-26', '28 of 28 runs failed', 'Nobody watching.', 'A nightly off-site backup failed every run it ever made, unnoticed, until someone looked.', 'Recorded 26 Oct 2026');
insert into measures (position, as_of, label, bar, current, standing) values
  (1, '2026-10-26', 'Merges not made by the integrator', '0', '0', 'hit'),
  (2, '2026-10-26', '`build` ran to merge on real site issues', '3–5', '4', 'hit'),
  (3, '2026-10-26', '`propose` reached the founder as one queue item, one sitting', '2 issues', '1', 'pending'),
  (4, '2026-10-26', 'Lines deleted within two weeks of being written', 'falling', 'first week', 'pending'),
  (5, '2026-10-26', 'Age of the oldest open `red` issue', 'hours, not days', 'none open', 'hit'),
  (6, '2026-10-26', 'Stars, traffic, installs', 'not a measure', '—', null);
insert into record_entries (position, as_of, headline, entry) values
  (1, '2026-10-26', 'this build', 'Reading the live page after issue #6 merged found three claims on it that were not true. Step 4 still read `Running · 1 of 2`, though its done condition — one real run of `propose` on this site''s brief — was met by the queue item on [issue #1](https://github.com/todd450/founding-agents-site/issues/1). At 1440px the band''s verdict line ended at the exact left edge of the STEP 1 column, because only the step columns carried the gutter and the rule that divide them. And the entry below undercounted its own review at three rounds when it took four. The first two were written in [PR #8](https://github.com/todd450/founding-agents-site/pull/8) and the third in [PR #9](https://github.com/todd450/founding-agents-site/pull/9), and all three passed review there: the step tests asked whether a step carried a name, a state, a date and a link, never whether the state was still true, and nothing read the band''s CSS at a width or the numbers in the record''s own prose. Fixed for [issue #10](https://github.com/todd450/founding-agents-site/issues/10) in [PR #11](https://github.com/todd450/founding-agents-site/pull/11), the fourth real site issue through `build` to merge.'),
  (2, '2026-10-26', 'issue #6''s review took four rounds', 'Issue #6 filled in the last four sections: how a change flows, what this is not, the measures table and this record. It drops the mockup''s open question about the product''s name — the rename below settled that before this issue was built — and records the rename here instead. Built in [PR #9](https://github.com/todd450/founding-agents-site/pull/9), which is also the third real site issue through `build` to merge, closing build step 3 at 3 of 3–5. Its own review took four rounds. The first found the same shape of gap as issue #5''s, one issue later — the record''s date-order test reported on the entries it could parse rather than on all of them — two of this build''s new prose blocks running the full shell width while the paragraph directly above each stayed capped, and nothing checking that the two files the flow section links to are still there to be served, which is the 404 that freezes every merge. The first two fixes were themselves incomplete: the date-order count matched a literal `<li>`, so an entry carrying a class stayed invisible, and two more prose blocks were left uncapped, four in all. The second round found both again, and the third round found that same literal-tag blind spot in two more tests — the flow rail''s role labels and the measures table''s rows — and this paragraph undercounting its own prose blocks and its own rounds. All were fixed on the same PR, and a fourth round approved it.'),
  (3, '2026-10-26', 'issue #5''s review caught its own blind spot', '[PR #8](https://github.com/todd450/founding-agents-site/pull/8) filled in the status band and the four costs for [issue #5](https://github.com/todd450/founding-agents-site/issues/5). Its review found that step 3 named only PR #7''s merge, though PR #8 was itself a second real merge that would have falsified "1 of 3–5" the moment it landed; that the step test could not tell four copies of the same step apart; and that the live red-line check''s only text test was the substring "blocked", which "Nothing is blocked" also contains. All three were fixed before merge.'),
  (4, '2026-10-26', 'the repo and the page both became Founding Agents', 'During issue #4''s review the founder renamed this repository from `agent-team-site` to `founding-agents-site` and moved its GitHub Pages address to match, settling the mockup''s one open question about what this product is called. Repository settings are not public, so this line carries a date and no link.'),
  (5, '2026-10-26', 'issue #4 took three rounds of review', '[PR #7](https://github.com/todd450/founding-agents-site/pull/7) added the design tokens and the page shell for [issue #4](https://github.com/todd450/founding-agents-site/issues/4). Review found the colour and font checks missed inline `style=` attributes and extra `<style>` blocks, the link checks let protocol-relative URLs through, and a page-level override could still smuggle in a literal colour or font while every test passed — each was fixed, then the founder narrowed the suite, dropping a full CSS-linter check that was never in the issue''s appetite.'),
  (6, '2026-10-26', 'the rule that would have frozen every merge', 'The brief nearly shipped the rule "every claim links to a file or merged PR in the plugin repo." That repo is private and the nightly check crawls every link with no credentials, so each link would answer 404, open `red`, and stop the integrator merging anything. Replaced before it reached [the brief](https://github.com/todd450/founding-agents-site/issues/1): claims link to this repo''s own public files, PRs and issues, or they carry a date and no link.'),
  (7, '2026-10-26', 'the order bent', '[This brief](https://github.com/todd450/founding-agents-site/issues/1) was played by hand on 24 Oct, before `propose` existed as a run. The product lead rewrote it on 26 Oct, so the lane''s first real run is a re-run of an already-decided brief. The 24 Oct decision and the 25 Oct change stay in the issue''s comments rather than being tidied away.'),
  (8, '2026-10-25', 'the premise changed after the decision', 'The site was decided go on 24 Oct with a target of five outside users in four weeks. The plugin repo stayed private, so the target became unmeasurable and the launch page had no reader. The bet was cut to a test bed at one day instead of being kept alive on a target nobody could check.'),
  (9, '2026-10-25', 'roles that did not exist yet', '`build` and `propose` had run only on throwaway repos. Steps 3 and 4 had no real product to run on, which is the job this site took.'),
  (10, '2026-10-24', 'protection worked by surprise', 'Branch protection on `main` blocked a builder session''s push before the builder knew the rule existed. It is the behaviour the team wanted, found the way nobody plans for.');
